<?php
require_once dirname(__DIR__).'/config/database.php';require_once dirname(__DIR__).'/includes/layout.php';require_login('student');$q=$pdo->prepare('SELECT c.*,e.enrolled_at FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE e.user_id=? ORDER BY e.enrolled_at DESC');$q->execute([current_user()['id']]);$courses=$q->fetchAll();start_page('My learning','learning'); ?>
<?php if($courses): ?><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><?php foreach($courses as $c): ?><article class="card course-card"><span class="course-code"><?= e($c['code']) ?> · ENROLLED</span><h2 class="mt-4 text-lg font-bold text-slate-800"><?= e($c['title']) ?></h2><p class="mt-2 flex-1 text-sm leading-6 text-slate-600"><?= e($c['description']) ?></p><div class="mt-4 border-t border-slate-100 pt-3 text-xs text-slate-500">Enrolled <?= e(date('M j, Y',strtotime($c['enrolled_at']))) ?> · <?= e($c['duration']) ?></div><div class="alert alert-success mt-4">Course access is active.</div></article><?php endforeach ?></div><?php else: ?><div class="card py-12 text-center"><h2 class="card-title">Your learning starts here</h2><p class="muted mt-2">Browse the available courses and enroll for KSh 5.</p><a class="btn-primary mt-5" href="<?= e(app_url('courses.php')) ?>">Browse courses</a></div><?php endif ?><?php end_page(); ?>
